it.each(vectors)("preserves WebP $name", async (v) => {
  const input = new Uint8Array(Buffer.from(v.input, "base64")),
    signal = new AbortController().signal,
    memory = new Uint8Array(16 * 1024 * 1024),
    borrowed = new Uint8Array(4096);
  let end = 19;
  const source = {
    size: input.length,
    async read(at: number, length: number) {
      expect(length).toBeLessThanOrEqual(4096);
      borrowed.fill(129);
      borrowed.set(input.subarray(at, at + length));
      return borrowed.subarray(0, length);
    }
  };
  const storage = {
    allocate(length: number) {
      const at = end;
      end += length;
      expect(end).toBeLessThan(memory.length);
      return at;
    },
    async read(at: number, length: number) {
      expect(length).toBeLessThanOrEqual(4096);
      borrowed.fill(211);
      borrowed.set(memory.subarray(at, at + length));
      return borrowed.subarray(0, length);
    },
    async write(at: number, bytes: Uint8Array) {
      expect(bytes.length).toBeLessThanOrEqual(4096);
      memory.set(bytes, at);
    }
  };
  const { position, ...meta } = await decodeWebpToStorage(source, storage, signal);
  expect(meta).toEqual(v.meta);
  expect(
    createHash("sha256")
      .update(memory.subarray(position, position + meta.width * meta.height * 4))
      .digest("hex")
  ).toBe(v.hash);
  const { data, ...buffered } = decodeWebpImage(input);
  expect(buffered).toEqual(v.meta);
  expect(createHash("sha256").update(data).digest("hex")).toBe(v.hash);
});

import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import sharp from "./index.js";
it.each(["png", "webp"] as const)(
  "converts retained WebP files to %s and resolves WebP overlays through caller storage",
  async (format) => {
    const fs = new MemoryFileSystem(),
      input = new Uint8Array(Buffer.from(vectors.at(-1)!.input, "base64"));
    const overlay = new Uint8Array(Buffer.from(vectors[0]!.input, "base64"));
    await fs.writeFile("/in", input);
    await fs.writeFile("/overlay", overlay);
    const guarded = new Proxy(fs, {
      get(target, key) {
        if (key === "readFile" || key === "writeFile")
          return () => {
            throw new Error("whole-file I/O forbidden");
          };
        const value = Reflect.get(target, key, target);
        return typeof value === "function" ? value.bind(target) : value;
      }
    });
    const expected = sharp(input)
      .composite([{ input: overlay }])
      .resize(19, 17)
      .toFormat(format)
      .toBufferWithObjectSync();
    const info = await sharp("/in", { filesystem: guarded })
      .composite([{ input: "/overlay" }])
      .resize(19, 17)
      .toFormat(format)
      .toFile("/out");
    const actual = await fs.readFile("/out");
    expect(info).toEqual({ ...expected.info, size: actual.length });
    expect(sharp(actual).raw().toBufferSync()).toEqual(sharp(expected.data).raw().toBufferSync());
    expect((await fs.readdir("/")).map((e) => e.name)).toEqual(["in", "out", "overlay"]);
  }
);

import { decodeWebpLossless } from "./codecs/webp-decode-kernel.js";
it("retains backing addresses above 32 bits in Huffman group records", () => {
  const input = new Uint8Array(Buffer.from(vectors[2]!.input, "base64"));
  let start = 12;
  const view = new DataView(input.buffer);
  while (String.fromCharCode(...input.subarray(start, start + 4)) !== "VP8L")
    start += 8 + view.getUint32(start + 4, true) + (view.getUint32(start + 4, true) & 1);
  const length = view.getUint32(start + 4, true),
    kernel = decodeWebpLossless(start + 8, length, 1, 1),
    words = new Map<number, number>();
  let end = 2 ** 32 + 8,
    value = 0;
  while (true) {
    const step = kernel.next(value);
    if (step.done) {
      expect(words.get(step.value.position)).toBe(0xff0c2238);
      break;
    }
    const effect = step.value;
    if (effect.kind === "byte") value = input[effect.position]!;
    else if (effect.kind === "allocate") {
      value = end;
      end += effect.length;
    } else if (effect.kind === "get") value = words.get(effect.position) ?? 0;
    else words.set(effect.position, effect.value);
  }
});
for (const event of ["source", "allocate", "read", "write"] as const)
  for (const cancel of [false, true])
    it(`propagates ${event} ${cancel ? "cancellation" : "failure"} without synthetic fallback`, async () => {
      const input = new Uint8Array(Buffer.from(vectors.at(-1)!.input, "base64")),
        controller = new AbortController(),
        reason = new Error(event),
        memory = new Uint8Array(4 * 1024 * 1024);
      let end = 0;
      const hit = (kind: typeof event) => {
        if (kind === event) {
          if (cancel) controller.abort(reason);
          else throw reason;
        }
      };
      const source = {
        size: input.length,
        async read(at: number, length: number) {
          hit("source");
          return input.subarray(at, at + length);
        }
      };
      const storage = {
        allocate(length: number) {
          hit("allocate");
          const at = end;
          end += length;
          return at;
        },
        async read(at: number, length: number) {
          hit("read");
          return memory.subarray(at, at + length);
        },
        async write(at: number, bytes: Uint8Array) {
          hit("write");
          memory.set(bytes, at);
        }
      };
      await expect(decodeWebpToStorage(source, storage, controller.signal)).rejects.toBe(reason);
    });

import { deflateSync } from "node:zlib";
for (const variant of ["valid", "truncated", "wrong-size", "invalid"] as const)
  it(`streams legacy zlib WebP ${variant} with independent compressed bytes`, async () => {
    const width = 257,
      height = 129,
      pixels = new Uint8Array(width * height * 4);
    let random = 123456789;
    for (let i = 0; i < pixels.length; i++) {
      random ^= random << 13;
      random ^= random >>> 17;
      random ^= random << 5;
      pixels[i] = random & 255;
    }
    const compressed = new Uint8Array(
      deflateSync(variant === "wrong-size" ? pixels.subarray(0, pixels.length - 4) : pixels)
    );
    if (variant === "invalid") compressed[8] ^= 255;
    const payload = new Uint8Array(6 + compressed.length - (variant === "truncated" ? 3 : 0));
    payload[0] = 47;
    new DataView(payload.buffer).setUint32(1, (width - 1) | ((height - 1) << 14) | (1 << 28), true);
    payload.set(compressed.subarray(0, payload.length - 6), 6);
    const input = new Uint8Array(20 + payload.length + (payload.length & 1)),
      view = new DataView(input.buffer);
    input.set([82, 73, 70, 70], 0);
    view.setUint32(4, input.length - 8, true);
    input.set([87, 69, 66, 80, 86, 80, 56, 76], 8);
    view.setUint32(16, payload.length, true);
    input.set(payload, 20);
    // Invalid legacy bytes are also valid input to the existing VP8L fallback; freeze that contract via buffered decoding.
    const expected = decodeWebpImage(input),
      memory = new Uint8Array(16 * 1024 * 1024),
      signal = new AbortController().signal;
    let end = 0,
      reads = 0;
    const image = await decodeWebpToStorage(
      {
        size: input.length,
        async read(at, length) {
          expect(length).toBeLessThanOrEqual(4096);
          reads++;
          return input.subarray(at, at + length);
        }
      },
      {
        allocate(length) {
          const at = end;
          end += length;
          expect(end).toBeLessThan(memory.length);
          return at;
        },
        async read(at, length) {
          expect(length).toBeLessThanOrEqual(4096);
          return memory.subarray(at, at + length);
        },
        async write(at, bytes) {
          expect(bytes.length).toBeLessThanOrEqual(4096);
          memory.set(bytes, at);
        }
      },
      signal
    );
    expect(reads).toBeGreaterThan(32);
    expect(memory.subarray(image.position, image.position + pixels.length)).toEqual(expected.data);
    if (variant === "valid") expect(expected.data).toEqual(pixels);
  });
